# LRU cache implemented with collections.OrderedDict (Redis allkeys-lru semantics)
from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self._store = OrderedDict()

    def get(self, key):
        if key not in self._store:
            return None
        self._store.move_to_end(key)   # mark as recently used
        return self._store[key]

    def set(self, key, value):
        if key in self._store:
            self._store.move_to_end(key)
        self._store[key] = value
        if len(self._store) > self.capacity:
            evicted_key, _ = self._store.popitem(last=False)  # remove LRU
            print(f'  evicted: {evicted_key}')

cache = LRUCache(capacity=3)
for k, v in [('a', 1), ('b', 2), ('c', 3)]:
    cache.set(k, v)
    print(f'SET {k}={v}  keys={list(cache._store)}')

cache.get('a')          # 'a' becomes MRU
print(f'GET a -> {cache.get("a")}')
cache.set('d', 4)       # should evict 'b' (LRU after 'a' was accessed)
print(f'After SET d=4: keys={list(cache._store)}')
